const data = msg.payload;
const MIN = parseFloat(env.get('MIN_VALID_VALUE')) || -50;
const MAX = parseFloat(env.get('MAX_VALID_VALUE')) || 1000;

// Validate required fields
if (!data || typeof data !== 'object') {
    node.warn('Dropped: payload is not a JSON object');
    return null;
}

if (!data.sensor_id) {
    node.warn('Dropped: missing sensor_id', msg);
    return null;
}

if (typeof data.value !== 'number') {
    node.warn(`Dropped: value is not a number (got ${typeof data.value})`, msg);
    return null;
}

// Range check
if (data.value < MIN || data.value > MAX) {
    node.warn(`Dropped: value ${data.value} out of range [${MIN}, ${MAX}]`, msg);
    return null;
}

// Attach metadata
msg.sensor_id = data.sensor_id;
msg.received_at = Date.now();
return msg;

const raw = msg.payload;

// Normalize to standard schema
msg.payload = {
    sensor_id: raw.sensor_id,
    value: Math.round(raw.value * 100) / 100,  // 2 decimal places
    unit: raw.unit || 'unknown',
    location: raw.location || msg.topic.split('/')[1] || 'unknown',
    quality: raw.quality || 'good',
    received_at: msg.received_at,
    processed_at: Date.now(),
    source_topic: msg.topic
};

msg.topic = env.get('MQTT_OUTPUT_TOPIC') || 'processed/sensors';
return msg;

const status = msg.status;
if (status.fill === 'red') {
    node.warn(`MQTT disconnected: ${status.text}`);
    msg.payload = {
        event: 'mqtt_disconnect',
        broker: env.get('MQTT_BROKER_HOST'),
        status: status.text,
        ts: new Date().toISOString()
    };
    return msg;
} else if (status.fill === 'green') {
    node.log(`MQTT connected: ${status.text}`);
    return null;  // suppress normal connection messages
}
return null;

node.error(`Pipeline error in ${msg.error.source.name}: ${msg.error.message}`);
msg.payload = {
    error: true,
    source_node: msg.error.source.name,
    source_type: msg.error.source.type,
    message: msg.error.message,
    original_payload: msg.payload,
    ts: new Date().toISOString()
};
return msg;
